<?php require dirname(__DIR__,2).'/app/bootstrap.php'; use App\Services\AdminAuthService; if(AdminAuthService::user()){redirect('admin/');} $error=null; $return=$_GET['return']??'/admin/'; if(!str_starts_with($return,'/')||str_starts_with($return,'//'))$return='/admin/'; if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_verify($_POST['_csrf_token']??null)){$error='Your form session expired. Please try again.';}else{[$ok,$message]=AdminAuthService::login($_POST['email']??'',$_POST['password']??'',$_SERVER['REMOTE_ADDR']??'0.0.0.0');if($ok){redirect($_POST['return']??'admin/');}$error=$message;}} ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><link rel="stylesheet" href="<?= e(asset('admin/assets/vendor/bootstrap/css/bootstrap.min.css')) ?>"><link rel="stylesheet" href="<?= e(asset('admin/assets/css/main.css')) ?>"><title>Sign in · ShopWise Kenya Admin</title></head><body><main class="container py-5" style="max-width:480px"><div class="card"><div class="card-body p-4"><h1 class="h3">ShopWise Kenya administration</h1><p class="text-muted">Sign in with an active staff or administrator account.</p><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post"><?= csrf_field() ?><input type="hidden" name="return" value="<?= e($return) ?>"><div class="mb-3"><label class="form-label">Email address</label><input class="form-control" type="email" name="email" required autocomplete="email"></div><div class="mb-3"><label class="form-label">Password</label><input class="form-control" type="password" name="password" required autocomplete="current-password"></div><button class="btn btn-primary w-100">Sign in securely</button></form><p class="mt-3 mb-0"><a href="<?= e(url('admin/forgot-password.php')) ?>">Forgot password?</a></p></div></div></main></body></html>
